macro_rules! deps {
    () => {
        ArcSwapAny!();
    };
}

macro_rules! RefCnt {
    () => {
        deps!();
        # [doc = " A trait describing smart reference counted pointers."] # [doc = ""] # [doc = " Note that in a way [`Option<Arc<T>>`][Option] is also a smart reference counted pointer, just"] # [doc = " one that can hold NULL."] # [doc = ""] # [doc = " The trait is unsafe, because a wrong implementation will break the [ArcSwapAny]"] # [doc = " implementation and lead to UB."] # [doc = ""] # [doc = " This is not actually expected for downstream crate to implement, this is just means to reuse"] # [doc = " code for [Arc] and [`Option<Arc>`][Option] variants. However, it is theoretically possible (if"] # [doc = " you have your own [Arc] implementation)."] # [doc = ""] # [doc = " It is also implemented for [Rc], but that is not considered very useful (because the"] # [doc = " [ArcSwapAny] is not `Send` or `Sync`, therefore there's very little advantage for it to be"] # [doc = " atomic)."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Aside from the obvious properties (like that incrementing and decrementing a reference count"] # [doc = " cancel each out and that having less references tracked than how many things actually point to"] # [doc = " the value is fine as long as the count doesn't drop to 0), it also must satisfy that if two"] # [doc = " pointers have the same value, they point to the same object. This is specifically not true for"] # [doc = " ZSTs, but it is true for `Arc`s of ZSTs, because they have the reference counts just after the"] # [doc = " value. It would be fine to point to a type-erased version of the same object, though (if one"] # [doc = " could use this trait with unsized types in the first place)."] # [doc = ""] # [doc = " Furthermore, the type should be Pin (eg. if the type is cloned or moved, it should still"] # [doc = " point/deref to the same place in memory)."] # [doc = ""] # [doc = " [Arc]: std::sync::Arc"] # [doc = " [Rc]: std::rc::Rc"] # [doc = " [ArcSwapAny]: crate::ArcSwapAny"] pub unsafe trait RefCnt : Clone { # [doc = " The base type the pointer points to."] type Base ; # [doc = " Converts the smart pointer into a raw pointer, without affecting the reference count."] # [doc = ""] # [doc = " This can be seen as kind of freezing the pointer ‒ it'll be later converted back using"] # [doc = " [`from_ptr`](#method.from_ptr)."] # [doc = ""] # [doc = " The pointer must point to the value stored (and the value must be the same as one returned"] # [doc = " by [`as_ptr`](#method.as_ptr)."] fn into_ptr (me : Self) -> * mut Self :: Base ; # [doc = " Provides a view into the smart pointer as a raw pointer."] # [doc = ""] # [doc = " This must not affect the reference count ‒ the pointer is only borrowed."] fn as_ptr (me : & Self) -> * mut Self :: Base ; # [doc = " Converts a raw pointer back into the smart pointer, without affecting the reference count."] # [doc = ""] # [doc = " This is only called on values previously returned by [`into_ptr`](#method.into_ptr)."] # [doc = " However, it is not guaranteed to be 1:1 relation ‒ `from_ptr` may be called more times than"] # [doc = " `into_ptr` temporarily provided the reference count never drops under 1 during that time"] # [doc = " (the implementation sometimes owes a reference). These extra pointers will either be"] # [doc = " converted back using `into_ptr` or forgotten."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This must not be called by code outside of this crate."] unsafe fn from_ptr (ptr : * const Self :: Base) -> Self ; # [doc = " Increments the reference count by one."] # [doc = ""] # [doc = " Return the pointer to the inner thing as a side effect."] fn inc (me : & Self) -> * mut Self :: Base { Self :: into_ptr (Self :: clone (me)) } # [doc = " Decrements the reference count by one."] # [doc = ""] # [doc = " Note this is called on a raw pointer (one previously returned by"] # [doc = " [`into_ptr`](#method.into_ptr). This may lead to dropping of the reference count to 0 and"] # [doc = " destruction of the internal pointer."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This must not be called by code outside of this crate."] unsafe fn dec (ptr : * const Self :: Base) { drop (Self :: from_ptr (ptr)) ; } }
    };
}

RefCnt!();